 대화'에 참석해 시민들과 소통하는 시간을 가졌다. 시는 이날 △한반도 KTX 신설 관련 전라선 고속화 사업 역량 집중 △도시재생 뉴딜사업 예산 지원 확대 △전주권 광역철도 구축 △전북권 산재전문병원 익산 건립 지원 등을 핵심 건의사항으로 제시했다. 이는 교통 접근성 개선과 원도심 회복, 산업재해 대응 기반 확충 등 익산의 중장기 발전과 직결된 사안들이다. 특히 시는 전북 교통의 요충지이자 국가식품산업 중심지인 익산의 위상을 강조하며, 광역교통망 확충과 도시재생 사업에 대한 도 차원의 전략적 지원이 필요하다는 점을 분명히 했다. 이날 김 지사는 익산시 장애인종합복지관을 방문해 복지 현장을 살피고, 북부시장을 찾아 상인들과 만나 지역 경제 상황을 점검했다. 익산시는 현장 방문이 일회성에 그치지 않고, 복지와 민생 정책으로 이어질 수 있도록 지속적인 협력을 요청했다. 정헌율 시장은 "익산시민의 목소리를 직접 도에 전달할 수 있는 귀중한 시간이됐다"며 "익산의 현안은 곧 전북의 과제라는 마음으로 도와 긴밀히 협력해 시민이 체감할 수 있는 성과를 만들어가겠다"고 말했다. 기사이력코드 취재(기획) 취재(기획) 취재(제보) 취재(자료보완) 보도자료 SNS 서핑 기타(국내외 논문·학술지) 기타(증권사 리포트) 기타(타 언론사 후속보도) 메트로신문 정훈 기자 taiji1819@metroseoul.co.kr 다른기사 보기 Copyright ⓒ 메트로신문 & metroseoul.co.kr function goSearchPage(searchText){ location.href="/search?searchText="+encodeURI(searchText); return; } (function () { $.ajax({ type : "GET", url : "/wps/engine/rest/35?type=COMPONENT", success: function (data) { $("#ZxBejhqxJS").after(data); $("#ZxBejhqxJS").remove(); } }); })() 메트로신문 지면 PDF 보기 // 현재 날짜 구하기 var now = new Date(); // 요일 체크 (0 = 일요일, 1 = 월요일, ..., 6 = 토요일) var dayName = now.getDay(); // 주말이면 금요일 날짜로 바꾸기 if (dayName === 0) { // 일요일이면 now.setDate(now.getDate() - 2); // 금요일로 이동 } else if (dayName === 6) { // 토요일이면 now.setDate(now.getDate() - 1); // 금요일로 이동 } // MMddDate: MMDD 형식 var MMddDate = ("0" + (now.getMonth() + 1)).slice(-2) + ("0" + now.getDate()).slice(-2); // yyyyMMddDate: yyyy/MM/dd 형식 var yyyyMMddDate = now.getFullYear() + "/" + ("0" + (now.getMonth() + 1)).slice(-2) + "/" + ("0" + now.getDate()).slice(-2); // yyyyMMddDate2: yyyy-MM-dd 형식 var yyyyMMddDate2 = now.getFullYear() + "-" + ("0" + (now.getMonth() + 1)).slice(-2) + "-" + ("0" + now.getDate()).slice(-2); // 이미지 src URL 생성 var imageUrl = "https://pdf.metroseoul.co.kr/pdf/" + yyyyMMddDate + "/img/s10/kr_metro_1_" + MMddDate + "_01.jpg"; // HTML 요소에 값 삽입 document.getElementById('pdfImage').setAttribute('src', imageUrl); document.getElementById('pdfDate').textContent = yyyyMMddDat